    [Fact]
    public void Static_position_static_root() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(200.0f));
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(100.0f));
        tree.SetPositionType(root, PositionType.Static);
        tree.SetPadding(root, Edge.Top, StyleLength.Points(1.0f));
        tree.SetPadding(root, Edge.Right, StyleLength.Points(11.0f));
        tree.SetPadding(root, Edge.Bottom, StyleLength.Points(4.0f));
        tree.SetPadding(root, Edge.Left, StyleLength.Points(6.0f));

        var rootChild0 = tree.CreateNode();
        tree.SetDimension(rootChild0, Dimension.Height, StyleLength.Percent(50.0f));
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Percent(50.0f));
        tree.SetPositionType(rootChild0, PositionType.Absolute);
        tree.SetBorder(rootChild0, Edge.Top, StyleLength.Points(3.0f));
        tree.SetBorder(rootChild0, Edge.Right, StyleLength.Points(2.0f));
        tree.SetBorder(rootChild0, Edge.Bottom, StyleLength.Points(1.0f));
        tree.SetBorder(rootChild0, Edge.Left, StyleLength.Points(4.0f));
        tree.SetPadding(rootChild0, Edge.Top, StyleLength.Points(7.0f));
        tree.SetPadding(rootChild0, Edge.Right, StyleLength.Points(5.0f));
        tree.SetPadding(rootChild0, Edge.Bottom, StyleLength.Points(4.0f));
        tree.SetPadding(rootChild0, Edge.Left, StyleLength.Points(3.0f));
        tree.SetMargin(rootChild0, Edge.Top, StyleLength.Points(11.0f));
        tree.SetMargin(rootChild0, Edge.Right, StyleLength.Points(15.0f));
        tree.SetMargin(rootChild0, Edge.Bottom, StyleLength.Points(1.0f));
        tree.SetMargin(rootChild0, Edge.Left, StyleLength.Points(12.0f));
        tree.InsertChild(root, rootChild0, 0);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(200.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(18.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(12.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetHeight(rootChild0), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(200.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(24.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(12.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetHeight(rootChild0), Tolerance);
    }

